"""Execute JS and verify case/time/view controls in a real headless browser."""
import sys,html,json,re,subprocess,tempfile
from pathlib import Path
page=Path(sys.argv[1]).resolve();out=page.parent
script="<script>try{let checks={rendered:window.s08Rendered===true,cases:names.length>0};let before=$('map').toDataURL();$('time').value=25;$('time').dispatchEvent(new Event('input'));checks.time_changes=before!==$('map').toDataURL();$('time').value=100;$('time').dispatchEvent(new Event('input'));before=$('map').toDataURL();$('truth').click();checks.truth_toggle=before!==$('map').toDataURL();if(names.length>1){before=$('map').toDataURL();$('case').selectedIndex=1;$('case').dispatchEvent(new Event('change'));checks.case_changes=before!==$('map').toDataURL();}checks.passed=Object.values(checks).every(Boolean);let p=document.createElement('pre');p.id='qa';p.textContent=JSON.stringify(checks);document.body.append(p);}catch(e){let p=document.createElement('pre');p.id='qa';p.textContent=JSON.stringify({passed:false,error:String(e)});document.body.append(p);}</script>"
with tempfile.TemporaryDirectory(prefix='s08_browser_') as tmp:
    p=Path(tmp)/'qa.html';p.write_text(page.read_text().replace('</html>',script+'</html>'));args=['google-chrome','--headless','--disable-gpu','--no-first-run','--no-default-browser-check',f'--user-data-dir={tmp}/profile','--virtual-time-budget=3000','--window-size=1480,1200',f'--screenshot={out}/report_preview.png','--dump-dom',p.as_uri()];r=subprocess.run(args,capture_output=True,text=True,timeout=40);m=re.search('<pre id="qa">(.*?)</pre>',r.stdout);result=json.loads(html.unescape(m.group(1))) if m else dict(passed=False,error='QA DOM missing');result.update(exit_code=r.returncode,command=args);(out/'browser_check.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result));raise SystemExit(0 if result['passed'] and r.returncode==0 else 1)
